  'help.send': 'Pošalji tiket',
  'help.ticketSent': 'Tiket poslat!',
  'help.ticketSentDesc': 'Primili smo tvoju molbu. Naš tim će odgovoriti putem emaila u roku od 24 sata.',
  'help.close': 'Zatvori',
  'help.ticketError': 'Greška prilikom slanja tiketa. Pokušaj ponovo.',
  'help.type.cant_login': 'Ne mogu da se prijavim',
  'help.type.email_issue': 'Problem sa emailom',
  'help.type.security': 'Bezbednost',
  'help.type.other': 'Drugo',
  'help.faq.cantLogin.q': 'Ne mogu da pristupim svom nalogu',
  'help.faq.cantLogin.a': 'Proveri da li koristiš ispravnu email adresu i lozinku. Ako si zaboravio lozinku, klikni na "Zaboravio si lozinku?" na ekranu za prijavu. Ako problem i dalje traje, napravi tiket za podršku.',
  'help.faq.notReceiving.q': 'Ne primam emailove',
  'help.faq.notReceiving.a': 'Prvo proveri folder Spam. Uveri se da ti je skladište prazno. Ako problem i dalje postoji, potvrdi da pošiljalac ima ispravnu adresu i napravi tiket.',
  'help.faq.cantSend.q': 'Ne mogu da pošaljem emailove',
  'help.faq.cantSend.a': 'Proveri svoju internet konekciju i da li je adresa primaoca ispravna. Proveri da li dodaci ne prelaze 25MB. Pokušaj ponovo za nekoliko minuta.',
  'help.faq.forgotPassword.q': 'Zaboravio sam svoju lozinku',
  'help.faq.forgotPassword.a': 'Na ekranu za prijavu, klikni na "Zaboravio si lozinku?" i prati uputstva za resetovanje lozinke putem emaila za oporavak.',
  'help.faq.accountSecurity.q': 'Mislim da je moj nalog kompromitovan',
  'help.faq.accountSecurity.a': 'Odmah promeni svoju lozinku. Proveri folder Poslato za poruke koje nisi poslao. Aktiviraj dvostepenu autentifikaciju u Podešavanjima > Bezbednost. Ako je potrebno, napravi hitan tiket.',
  'help.faq.appAccess.q': 'Kako da pristupim aplikaciji na telefonu?',
  'help.faq.appAccess.a': 'Možeš pristupiti Chatyy-u putem pregledača na chatyy.com.br, ili preuzeti našu aplikaciju iz prodavnice aplikacija na tvom uređaju.',
  'privacy.title': 'Politika Privatnosti',
  'privacy.subtitle': 'Kako štitimo i obrađujemo tvoje podatke',
  'privacy.lastUpdated': 'Poslednja izmena: Mart 2026',
  'privacy.dataCollection.title': 'Prikupljanje Podataka',
  'privacy.dataCollection.body': 'Prikupljamo samo informacije potrebne za uslugu emaila: tvoje ime, email adresu i sadržaj poslatih i primljenih poruka. Ne prodajemo niti delimo tvoje lične podatke sa trećim stranama u marketinške svrhe.',
  'privacy.dataUsage.title': 'Kako Koristimo Tvoje Podatke',
  'privacy.dataUsage.body': 'Tvoji podaci se koriste isključivo za rad i poboljšanje usluge emaila, uključujući isporuku poruka, filtriranje spama, AI funkcije (uz tvoju saglasnost) i bezbednost naloga.',
  'privacy.dataSecurity.title': 'Bezbednost Podataka',
  'privacy.dataSecurity.body': 'Koristimo industrijske standarde enkripcije (TLS/SSL) za sve podatke u tranzitu i u mirovanju. Sesije su zaštićene enkriptovanim tokenima i CSRF zaštitom. Redovno auditujemo naše bezbednosne prakse.',
  'privacy.cookies.title': 'Kolačići i Lokalno Skladištenje',
  'privacy.cookies.body': 'Koristimo neophodne kolačiće i lokalno skladištenje da bismo održali tvoju sesiju, zapamtili tvoje preferencije (tema, jezik) i pružili glatko iskustvo. Ne koristimo kolačiće za praćenje trećih strana.',
  'privacy.thirdParties.title': 'Usluge Trećih Strana',
  'privacy.thirdParties.body': 'Možemo koristiti usluge trećih strana za specifične funkcionalnosti kao što su AI (Anthropic Claude) i push obaveštenja. Ove usluge slede svoje politike privatnosti i obrađuju samo minimum potrebnih podataka.',
  'privacy.rights.title': 'Tvoja Prava',
  'privacy.rights.body': 'Imaš pravo da pristupiš, ispraviš, eksportuješ ili obrišeš svoje lične podatke u bilo kojem trenutku. Možeš upravljati svojim podacima u Podešavanjima ili kontaktirajući našu podršku.',
  'privacy.contact.title': 'Kontaktiraj Nas',
  'privacy.contact.body': 'Za pitanja o privatnosti ili zahteve za podatke, kontaktiraj nas na privacy@chatyy.com.br. Odgovorićemo u roku od 30 dana.',
  'terms.title': 'Uslovi Korišćenja',
  'terms.subtitle': 'Pravila korišćenja Chatyy-a',
  'terms.lastUpdated': 'Poslednja izmena: Mart 2026',
  'terms.acceptance.title': 'Prihvatanje Uslova',
  'terms.acceptance.body': 'Pristupanjem ili korišćenjem Chatyy-a, slažeš se sa ovim Uslovima Korišćenja. Ako se ne slažeš sa bilo kojim delom ovih uslova, nemoj koristiti uslugu.',
  'terms.services.title': 'Opis Usluga',
  'terms.services.body': 'Chatyy pruža usluge komunikacije putem emaila uključujući slanje, primanje i upravljanje emailovima, kao i AI funkcije, integraciju sa kalendarom i videokonferencijama.',
  'terms.accounts.title': 'Korisnički Nalozi',
  'terms.accounts.body': 'Ti si odgovoran za održavanje bezbednosti svojih akreditiva. Ne deli svoju lozinku niti dozvoli neovlašćen pristup svom nalogu. Moraš imati najmanje 13 godina da bi koristio ovu uslugu.',
  'terms.conduct.title': 'Prihvatljivo Korišćenje',
  'terms.conduct.body': 'Slažeš se da nećeš koristiti uslugu za slanje spama, malvera, phishing ili bilo kojeg ilegalnog sadržaja. Ne pokušavaj da pristupiš nalozima drugih korisnika ili ometaš infrastrukturu usluge.',
  'terms.content.title': 'Vlasništvo nad Sadržajem',
  'terms.content.body': 'Zadržavaš vlasništvo nad svim sadržajem koji kreiraš i šalješ putem usluge. Ne tvrdimo vlasništvo nad tvojim emailovima ili dodacima. Možemo obraditi sadržaj po potrebi da bismo pružili uslugu.',
  'terms.limitation.title': 'Ograničenje Odgovornosti',
  'terms.limitation.body': 'Chatyy se pruža "kako jeste". Težimo 99,9% dostupnosti, ali ne garantujemo neprekidnu uslugu. Nismo odgovorni za indirektne, slučajne ili posledične štete proizašle iz korišćenja usluge.',
  'terms.termination.title': 'Zatvaranje Naloga',
  'terms.termination.body': 'Možemo obustaviti ili zatvoriti naloge koji krše ove uslove. Možeš obrisati svoj nalog u bilo kojem trenutku u Podešavanjima. Nakon zatvaranja, tvoji podaci će biti obrisani u roku od 30 dana.',
  'terms.changes.title': 'Izmene Uslova',
  'terms.changes.body': 'Možemo povremeno ažurirati ove uslove. Obavestićemo te o značajnim izmenama putem emaila ili obaveštenja u aplikaciji. Nastavak korišćenja nakon izmena predstavlja prihvatanje ažuriranih uslova.',
