  'plans.faqWhatIsPlus': 'Šta je Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'To je premium plan Chatyy koji štiti sve tvoje razgovore, fotografije i video zapise. Sa Chatyy One, čak i ako nešto slučajno obrišeš, možeš to povratiti u roku od 30 dana. Pored toga, dobijaš 200GB skladišta, One AI kao ličnog asistenta, i možeš slati datoteke do 100MB.',
  'plans.faqCancelAnswer': 'Tvoj plan ostaje aktivan do kraja plaćenog perioda. Nakon toga, vraćaš se na besplatni plan. Tvoje fotografije i video zapisi koji premašuju 15GB biće sačuvani još 30 dana da ih preuzmeš.',
